package tv.own.owntv.features.settings

import java.io.File

/** Rotate only names generated by this feature, after the newest encrypted file is published. */
internal object AutomaticBackupFiles {
    private val ownedName = Regex("owntv-auto-[0-9]+-[0-9a-f-]{36}\\.own")
    fun rotate(folder: File) {
        folder.listFiles()?.filter { it.isFile && ownedName.matches(it.name) }
            ?.sortedByDescending { it.name.substringAfter("owntv-auto-").substringBefore('-').toLongOrNull() ?: 0L }
            ?.drop(3)?.forEach { it.delete() }
    }
}
